mapper.select:
SELECT * FROM test_case_run
WHERE workspace_id = #{workspaceId}
ORDER BY created_at ASC, id ASC

mapper.update:
UPDATE test_case_run
SET bug_task_id = NULL
WHERE workspace_id = #{workspaceId}
  AND bug_task_id IN
  #{taskId}

mapper.select:
SELECT * FROM test_case_run
WHERE workspace_id = #{workspaceId} AND case_id = #{caseId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM test_case_run
WHERE workspace_id = #{workspaceId}
  AND case_id IN (SELECT id FROM test_case WHERE workspace_id = #{workspaceId} AND req_id = #{reqId})
